<?php

// Loaded before every request by the orb's `app` service only (see .amp/php/amplify.ini).
// Generated by Amplify (https://github.com/springloadedco/amplify).
//
// The Amp portal terminates HTTPS and forwards plain HTTP with X-Forwarded-Proto. Marking those
// requests as HTTPS makes Laravel generate https:// URLs and validate signed URLs without
// trustProxies() in bootstrap/app.php, so the app's code is unchanged.
if (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? null) === 'https') {
    $_SERVER['HTTPS'] = 'on';
}
